/**
 * Fogged Glass. Designed & built by Aakash Mehra.
 *
 * A photo behind a fogged, wet window. Click and drag to wipe the glass clean; scroll (or press
 * [ and ]) to change the size of the wipe. Wiped strokes leave faint streaks and water beads on
 * their edges, drops gather and run down through the fog leaving clear trails, and the fog slowly
 * condenses back over everything you wiped (`refog` seconds, 0 to keep it clean).
 *
 * All one canvas: the fog is a heavily blurred, hazed copy of the photo dotted with condensation,
 * and the larger drops refract a flipped, magnified view of the sharp photo, like real water does.
 */
"use client";

import { useEffect, useRef, type ReactNode } from "react";
import { cn } from "@/lib/utils";

const MIN_BRUSH = 14;
const MAX_BRUSH = 180;

// Default photo: an Unsplash city street at dusk (photo-1519501025264), cropped to 16:10 and embedded so the
// component makes no network request. Pass `src` to use your own.
const DEFAULT_SRC = "data:image/webp;base64,";

type Drip = { x: number; y: number; r: number; v: number; pause: number; life: number; seed: number };

const canvas = (w: number, h: number) => {
  const c = document.createElement("canvas");
  c.width = Math.max(1, Math.round(w));
  c.height = Math.max(1, Math.round(h));
  return c;
};
const ctx2d = (c: HTMLCanvasElement) => c.getContext("2d")!;
const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

// Down/up-sampling blur. Works everywhere (Safari has no ctx.filter). Radius ~ 2^passes px.
function blur(src: HTMLCanvasElement, passes: number) {
  const chain: HTMLCanvasElement[] = [];
  let cur = src;
  for (let i = 0; i < passes; i++) {
    const n = canvas(cur.width / 2, cur.height / 2);
    ctx2d(n).drawImage(cur, 0, 0, n.width, n.height);
    chain.push(cur);
    cur = n;
  }
  for (let i = passes - 1; i >= 0; i--) {
    const n = canvas(chain[i].width, chain[i].height);
    const x = ctx2d(n);
    x.imageSmoothingQuality = "high";
    x.drawImage(cur, 0, 0, n.width, n.height);
    cur = n;
  }
  return cur;
}

// Water drop outline: slightly lumpy, flatter on top, fuller at the bottom where gravity pulls.
function dropPath(x: CanvasRenderingContext2D, cx: number, cy: number, r: number, stretch: number, seed: number) {
  const n = r > 4 ? 48 : 20;
  x.beginPath();
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    const wob = r > 2.5 ? 1 + 0.03 * Math.sin(2 * a + seed) + 0.018 * Math.sin(3 * a + seed * 1.7) : 1;
    const s = Math.sin(a);
    x.lineTo(cx + Math.cos(a) * r * wob, cy + s * r * wob * (s > 0 ? stretch : 0.86));
  }
  x.closePath();
}

// A drop on glass is a flat lens: it shows a squeezed, upside-down view of the scene, a dark band
// along the top edge, a bright caustic pooled at the bottom, and one crisp highlight.
function drawDrop(x: CanvasRenderingContext2D, scene: HTMLCanvasElement, cx: number, cy: number, r: number, alpha = 1, stretch = 1, seed = cx * 0.13 + cy * 0.7) {
  if (r < 0.5 || alpha <= 0.01) return;
  x.save();
  x.globalAlpha = alpha;
  if (r > 1.5) {
    const sh = x.createRadialGradient(cx, cy + r * 0.35, r * 0.6, cx, cy + r * 0.35, r * 1.3);
    sh.addColorStop(0, "rgba(0,0,0,0.14)");
    sh.addColorStop(1, "rgba(0,0,0,0)");
    x.fillStyle = sh;
    x.fillRect(cx - r * 1.4, cy - r, r * 2.8, r * 2.8);
  }
  dropPath(x, cx, cy, r, stretch, seed);
  x.save();
  x.clip();
  const top = cy - r;
  const bot = cy + r * stretch;
  if (r > 1.2) {
    const span = r * 3.2;
    x.save();
    x.translate(cx, cy);
    x.scale(-1, -1);
    x.drawImage(scene, cx - span, cy - span, span * 2, span * 2, -r * 1.05, -r * 1.05 * stretch, r * 2.1, r * 2.1 * stretch);
    x.restore();
  } else {
    x.fillStyle = "rgba(255,255,255,0.18)";
    x.fillRect(cx - r, top, r * 2, bot - top);
  }
  const v = x.createLinearGradient(0, top, 0, bot);
  v.addColorStop(0, "rgba(0,0,0,0.26)");
  v.addColorStop(0.35, "rgba(255,255,255,0.04)");
  v.addColorStop(0.7, "rgba(255,255,255,0)");
  v.addColorStop(1, "rgba(255,255,255,0.24)");
  x.fillStyle = v;
  x.fillRect(cx - r * 1.2, top, r * 2.4, bot - top + 1);
  const e = x.createRadialGradient(cx, cy, r * 0.5, cx, cy, r * 1.08);
  e.addColorStop(0, "rgba(0,0,0,0)");
  e.addColorStop(1, "rgba(0,0,0,0.2)");
  x.fillStyle = e;
  x.fillRect(cx - r * 1.2, top, r * 2.4, bot - top + 1);
  const cy2 = cy + r * 0.55 * stretch;
  const c = x.createRadialGradient(cx, cy2, 0, cx, cy2, r * 0.55);
  c.addColorStop(0, "rgba(255,250,240,0.45)");
  c.addColorStop(1, "rgba(255,250,240,0)");
  x.fillStyle = c;
  x.fillRect(cx - r, cy2 - r * 0.6, r * 2, r * 1.2);
  x.restore();
  if (r > 2) {
    x.strokeStyle = "rgba(0,0,0,0.16)";
    x.lineWidth = Math.max(0.5, r * 0.06);
    x.stroke();
  }
  x.fillStyle = "rgba(255,255,255,0.9)";
  x.beginPath();
  x.ellipse(cx - r * 0.32, cy - r * 0.42, Math.max(0.35, r * 0.2), Math.max(0.25, r * 0.12), -0.5, 0, Math.PI * 2);
  x.fill();
  if (r > 3) {
    x.fillStyle = "rgba(255,255,255,0.45)";
    x.beginPath();
    x.arc(cx + r * 0.3, cy + r * 0.38 * stretch, r * 0.07, 0, Math.PI * 2);
    x.fill();
  }
  x.restore();
}

export type FoggedGlassProps = {
  /** Photo behind the glass. */
  src?: string;
  /** Describes the photo for screen readers. */
  alt?: string;
  /** Starting wipe radius in px (14 to 180). */
  brush?: number;
  /** Seconds for the fog to fully return over a wipe. 0 keeps wipes clean. */
  refog?: number;
  className?: string;
  children?: ReactNode;
};

export function FoggedGlass({
  src = DEFAULT_SRC,
  alt = "A city street at dusk seen through a fogged window",
  brush: brush0 = 56,
  refog = 16,
  className,
  children,
}: FoggedGlassProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sizeRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const root = rootRef.current!;
    const view = canvasRef.current!;
    const vx = ctx2d(view);
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const img = new Image();
    img.decoding = "async";
    img.src = src;

    let W = 0;
    let H = 0;
    let dpr = 1;
    let sharp = canvas(1, 1);
    let fog = canvas(1, 1);
    let mask = canvas(1, 1);
    let comp = canvas(1, 1);
    let mx = ctx2d(mask);
    let ready = false;
    let radius = clamp(brush0, MIN_BRUSH, MAX_BRUSH);
    let stamp = canvas(1, 1);
    let wet = canvas(1, 1); // beads left on the glass, drawn once
    let wx = ctx2d(wet);
    let drips: Drip[] = [];
    let nextDrip = 1;
    let refogAcc = 0;
    let pointer: { x: number; y: number } | null = null;
    let wiping: { x: number; y: number } | null = null;
    let sizeShownUntil = 0;
    let t = 0;

    const setSize = (show: boolean) => {
      if (!sizeRef.current) return;
      sizeRef.current.textContent = `Brush ${Math.round(radius)} px`;
      if (show) sizeShownUntil = t + 1.2;
    };

    // Brush: soft round falloff with a few weak spots, so a wipe leaves faint streaks behind.
    const buildStamp = () => {
      const r = radius * dpr;
      stamp = canvas(r * 2, r * 2);
      const s = ctx2d(stamp);
      const g = s.createRadialGradient(r, r, 0, r, r, r);
      g.addColorStop(0, "rgba(0,0,0,0.9)");
      g.addColorStop(0.6, "rgba(0,0,0,0.8)");
      g.addColorStop(1, "rgba(0,0,0,0)");
      s.fillStyle = g;
      s.fillRect(0, 0, r * 2, r * 2);
      s.globalCompositeOperation = "destination-out";
      for (let i = 0; i < radius * 0.5; i++) {
        const a = Math.random() * Math.PI * 2;
        const d = Math.sqrt(Math.random()) * r * 0.9;
        s.fillStyle = `rgba(0,0,0,${0.25 + Math.random() * 0.4})`;
        s.beginPath();
        s.arc(r + Math.cos(a) * d, r + Math.sin(a) * d, (0.4 + Math.random() * 1.2) * dpr, 0, Math.PI * 2);
        s.fill();
      }
    };

    const build = () => {
      const rect = root.getBoundingClientRect();
      W = rect.width;
      H = rect.height;
      dpr = Math.min(2, devicePixelRatio || 1);
      const pw = W * dpr;
      const ph = H * dpr;
      view.width = Math.round(pw);
      view.height = Math.round(ph);

      sharp = canvas(pw, ph);
      const sx = ctx2d(sharp);
      if (img.naturalWidth) {
        const k = Math.max(pw / img.naturalWidth, ph / img.naturalHeight);
        const iw = img.naturalWidth * k;
        const ih = img.naturalHeight * k;
        sx.drawImage(img, (pw - iw) / 2, (ph - ih) / 2, iw, ih);
      } else {
        const g = sx.createLinearGradient(0, 0, 0, ph);
        g.addColorStop(0, "#28324a");
        g.addColorStop(1, "#6a4a5c");
        sx.fillStyle = g;
        sx.fillRect(0, 0, pw, ph);
      }

      // Fog: blurred and hazed photo, then condensation.
      fog = blur(sharp, 5);
      const fx = ctx2d(fog);
      fx.fillStyle = "rgba(226,232,240,0.26)";
      fx.fillRect(0, 0, pw, ph);
      const lift = fx.createLinearGradient(0, 0, 0, ph);
      lift.addColorStop(0, "rgba(255,255,255,0.06)");
      lift.addColorStop(1, "rgba(255,255,255,0.12)"); // fog is denser low on a window
      fx.fillStyle = lift;
      fx.fillRect(0, 0, pw, ph);
      const fine = Math.round((W * H) / 22);
      for (let i = 0; i < fine; i++) {
        const x = Math.random() * pw;
        const y = Math.random() * ph;
        const r = (0.3 + Math.random() ** 3 * 1.3) * dpr;
        fx.fillStyle = `rgba(0,0,0,${0.03 + Math.random() * 0.04})`;
        fx.beginPath();
        fx.arc(x + r * 0.3, y + r * 0.4, r, 0, Math.PI * 2);
        fx.fill();
        fx.fillStyle = `rgba(255,255,255,${0.04 + Math.random() * 0.08})`;
        fx.beginPath();
        fx.arc(x, y, r, 0, Math.PI * 2);
        fx.fill();
      }
      // condensation drops: lots of small, some medium, a few big heavy ones
      const sizes: [number, () => number, number][] = [
        [(W * H) / 700, () => 0.4 + Math.random() ** 2 * 1, 1],
        [(W * H) / 6000, () => 1.4 + Math.random() * 1.8, 1.04],
        [(W * H) / 40000, () => 3.2 + Math.random() * 3.3, 1.15],
      ];
      for (const [count, size, stretch] of sizes) {
        for (let i = 0; i < count; i++) {
          const x = Math.random() * pw;
          const y = Math.random() * ph;
          const r = size() * dpr;
          if (r > 1.6 * dpr) {
            // a drop soaks up the fog around it, leaving a clearer halo
            const g = fx.createRadialGradient(x, y, r * 0.9, x, y, r * 1.9);
            g.addColorStop(0, "rgba(0,0,0,0.3)");
            g.addColorStop(1, "rgba(0,0,0,0)");
            fx.globalCompositeOperation = "destination-out";
            fx.fillStyle = g;
            fx.fillRect(x - r * 2.2, y - r * 2.2, r * 4.4, r * 4.4);
            fx.globalCompositeOperation = "source-over";
          }
          drawDrop(fx, sharp, x, y, r, 0.95, stretch * (0.95 + Math.random() * 0.1));
        }
      }

      mask = canvas(pw, ph);
      mx = ctx2d(mask);
      mx.fillStyle = "#000";
      mx.fillRect(0, 0, pw, ph);
      comp = canvas(pw, ph);
      wet = canvas(pw, ph);
      wx = ctx2d(wet);
      drips = [];
      buildStamp();
      ready = true;
    };

    const wipeTo = (x: number, y: number) => {
      if (!wiping) return;
      const r = radius * dpr;
      const ax = wiping.x * dpr;
      const ay = wiping.y * dpr;
      const bx = x * dpr;
      const by = y * dpr;
      const dist = Math.hypot(bx - ax, by - ay);
      const step = Math.max(1.5, r * 0.18);
      const n = Math.max(1, Math.ceil(dist / step));
      const nx = dist ? -(by - ay) / dist : 0;
      const ny = dist ? (bx - ax) / dist : 0;
      mx.globalCompositeOperation = "destination-out";
      for (let i = 1; i <= n; i++) {
        const px = ax + ((bx - ax) * i) / n;
        const py = ay + ((by - ay) * i) / n;
        mx.drawImage(stamp, px - r, py - r);
        // water pushed to the edges of the stroke beads up there: a ridge of tiny drops, a few big
        for (let k = 0; k < 2; k++) {
          if (Math.random() > 0.8) continue;
          const side = Math.random() < 0.5 ? -1 : 1;
          const d = r * (0.9 + Math.random() * 0.16);
          const br = (0.4 + Math.random() ** 2.5 * 2) * dpr;
          drawDrop(wx, sharp, px + nx * side * d + (Math.random() - 0.5) * 3 * dpr, py + ny * side * d + (Math.random() - 0.5) * 3 * dpr, br, 1, br > 1.6 * dpr ? 1.1 : 1);
        }
      }
      mx.globalCompositeOperation = "source-over";
      wiping = { x, y };
    };

    const local = (e: PointerEvent) => {
      const r = root.getBoundingClientRect();
      return { x: e.clientX - r.left, y: e.clientY - r.top };
    };
    const onDown = (e: PointerEvent) => {
      if (e.button !== 0) return;
      root.setPointerCapture(e.pointerId);
      const p = local(e);
      wiping = { x: p.x - 0.01, y: p.y };
      wipeTo(p.x, p.y);
    };
    const onMove = (e: PointerEvent) => {
      const p = local(e);
      pointer = e.pointerType === "mouse" ? p : null;
      wipeTo(p.x, p.y);
    };
    const onUp = () => {
      wiping = null;
    };
    const onLeave = () => {
      pointer = null;
    };
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      radius = clamp(radius * Math.exp(-e.deltaY * 0.002), MIN_BRUSH, MAX_BRUSH);
      buildStamp();
      setSize(true);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "[" && e.key !== "]") return;
      radius = clamp(radius * (e.key === "]" ? 1.15 : 1 / 1.15), MIN_BRUSH, MAX_BRUSH);
      buildStamp();
      setSize(true);
    };

    const step = (dt: number) => {
      t += dt;
      // fog condenses back; applied in chunks so 8-bit alpha actually moves
      if (refog > 0) {
        refogAcc += dt;
        if (refogAcc >= 0.2) {
          const k = Math.min(1, (refogAcc * 2.5) / refog);
          mx.globalAlpha = k;
          mx.fillStyle = "#000";
          mx.fillRect(0, 0, mask.width, mask.height);
          mx.globalAlpha = 1;
          wx.globalCompositeOperation = "destination-out"; // beads evaporate as the fog returns
          wx.globalAlpha = k;
          wx.fillRect(0, 0, wet.width, wet.height);
          wx.globalAlpha = 1;
          wx.globalCompositeOperation = "source-over";
          refogAcc = 0;
        }
      }

      // drops gather, then run down in fits and starts, clearing a trail
      if (!reduce && t > nextDrip && drips.length < 6) {
        nextDrip = t + 1 + Math.random() * 2.5;
        drips.push({ x: Math.random() * W, y: Math.random() * H * 0.6, r: 1.5 + Math.random() * 1.5, v: 0, pause: 0.4 + Math.random(), life: 4 + Math.random() * 8, seed: Math.random() * 10 });
      }
      for (const d of drips) {
        d.life -= dt;
        if (d.pause > 0) {
          d.pause -= dt;
          d.v *= 0.8;
        } else {
          d.v = Math.min(d.v + 260 * dt, 90 + d.r * 30);
          if (Math.random() < dt * 0.9) d.pause = 0.15 + Math.random() * 0.8;
        }
        const ox = d.x;
        const oy = d.y;
        d.y += d.v * dt;
        d.x += Math.sin(d.y * 0.04 + d.seed) * d.v * dt * 0.12;
        if (d.v > 1) {
          mx.globalCompositeOperation = "destination-out";
          mx.strokeStyle = "rgba(0,0,0,0.6)";
          mx.lineCap = "round";
          mx.lineWidth = d.r * 2.4 * dpr;
          mx.beginPath();
          mx.moveTo(ox * dpr, oy * dpr);
          mx.lineTo(d.x * dpr, d.y * dpr);
          mx.stroke();
          mx.globalCompositeOperation = "source-over";
          d.r = Math.max(1.2, d.r - dt * 0.12); // loses water along the way
          if (Math.random() < dt * 6) drawDrop(wx, sharp, (d.x + (Math.random() - 0.5) * d.r) * dpr, (d.y - d.r * 2) * dpr, (0.5 + Math.random() * d.r * 0.4) * dpr);
        }
      }
      drips = drips.filter((d) => {
        if (d.y > H + 10) return false;
        if (d.life > 0) return true;
        drawDrop(wx, sharp, d.x * dpr, d.y * dpr, d.r * dpr, 1, 1.15, d.seed);
        return false;
      });
    };

    const render = () => {
      const pw = view.width;
      const ph = view.height;
      const cx = ctx2d(comp);
      cx.globalCompositeOperation = "copy";
      cx.drawImage(fog, 0, 0);
      cx.globalCompositeOperation = "destination-in";
      cx.drawImage(mask, 0, 0);
      cx.globalCompositeOperation = "source-over";

      vx.setTransform(1, 0, 0, 1, 0, 0);
      vx.drawImage(sharp, 0, 0, pw, ph);
      vx.drawImage(comp, 0, 0);
      vx.drawImage(wet, 0, 0);
      for (const d of drips) drawDrop(vx, sharp, d.x * dpr, d.y * dpr, d.r * dpr * 1.15, 1, 1 + Math.min(0.5, d.v / 250), d.seed);

      if (pointer) {
        vx.setTransform(dpr, 0, 0, dpr, 0, 0);
        vx.lineWidth = 3;
        vx.strokeStyle = "rgba(0,0,0,0.25)";
        vx.beginPath();
        vx.arc(pointer.x, pointer.y, radius, 0, Math.PI * 2);
        vx.stroke();
        vx.lineWidth = 1.25;
        vx.strokeStyle = "rgba(255,255,255,0.85)";
        vx.stroke();
      }
      if (sizeRef.current) sizeRef.current.style.opacity = t < sizeShownUntil ? "1" : "0";
    };

    let raf = 0;
    let last = performance.now();
    const frame = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      if (ready) {
        step(dt);
        render();
      }
      raf = requestAnimationFrame(frame);
    };

    let built = false;
    const start = () => {
      if (built) return;
      built = true;
      build();
      setSize(false);
      raf = requestAnimationFrame(frame);
    };
    img.onload = start;
    img.onerror = start;
    if (img.complete && img.naturalWidth) start();

    let resizeTimer = 0;
    const ro = new ResizeObserver(() => {
      if (!built) return;
      clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(build, 120); // ponytail: resize re-fogs the glass; keep the mask if that ever annoys
    });
    ro.observe(root);
    root.addEventListener("pointerdown", onDown);
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerup", onUp);
    root.addEventListener("pointercancel", onUp);
    root.addEventListener("pointerleave", onLeave);
    root.addEventListener("wheel", onWheel, { passive: false });
    window.addEventListener("keydown", onKey);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(resizeTimer);
      ro.disconnect();
      img.onload = img.onerror = null;
      root.removeEventListener("pointerdown", onDown);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerup", onUp);
      root.removeEventListener("pointercancel", onUp);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("wheel", onWheel);
      window.removeEventListener("keydown", onKey);
    };
  }, [src, brush0, refog]);

  return (
    <div
      ref={rootRef}
      className={cn("relative h-dvh w-full cursor-none touch-none select-none overflow-hidden bg-neutral-900", className)}
    >
      <canvas ref={canvasRef} role="img" aria-label={alt} className="absolute inset-0 h-full w-full" />
      <div className="pointer-events-none absolute right-0 top-0 flex flex-col items-end p-5 text-right font-sans text-[13px] leading-relaxed text-white/80 [text-shadow:0_1px_3px_rgba(0,0,0,0.5)]">
        <span>Click and drag to wipe the glass</span>
        <span>Scroll to change the wipe size</span>
        <span ref={sizeRef} className="mt-1 tabular-nums opacity-0 transition-opacity duration-300" />
      </div>
      {children && <div className="absolute inset-x-0 bottom-0 flex justify-center p-5 font-sans">{children}</div>}
    </div>
  );
}

