import { FoggedGlass } from "@/components/ui/foggy-window-wipe";

export default function FoggedGlassDemo() {
  return (
    <FoggedGlass>
      <p className="m-0 text-[12px] text-white/60 [text-shadow:0_1px_3px_rgba(0,0,0,0.5)]">
        by{" "}
        <a
          href="https://aakashmehra.com/ref/foggedglass"
          target="_blank"
          rel="noopener noreferrer"
          className="text-white/85 underline-offset-4 hover:underline"
        >
          aakashmehra.com
        </a>
      </p>
    </FoggedGlass>
  );
}
